export const createTabsState = (options) => {
    const { tabs = [], onChange, indicator } = options;
    let activeTab = null;
    const initialActiveTab = tabs.find(tab => tab.isActive());
    if (initialActiveTab) {
        activeTab = initialActiveTab;
        if (indicator) {
            setTimeout(() => {
                indicator.moveToTab(initialActiveTab, true);
            }, 50);
        }
    }
    const activateTab = (tab, immediate = false) => {
        if (!tab || (activeTab === tab))
            return;
        if (activeTab) {
            activeTab.deactivate();
        }
        tab.activate();
        activeTab = tab;
        if (indicator) {
            setTimeout(() => {
                indicator.moveToTab(tab, immediate);
            }, 10);
        }
        if (onChange) {
            onChange({
                tab,
                value: tab.getValue()
            });
        }
    };
    const getActiveTab = () => {
        return activeTab;
    };
    const destroy = () => {
        activeTab = null;
    };
    return {
        activateTab,
        getActiveTab,
        destroy
    };
};
